All four changes are in place. Here's a summary of what was refactored and why:

---

### Refactoring Summary

**`SpringApplication.java`** — 3 changes:

1. **`printBanner` — extract `bannerMode` local variable** (lines 563–575)  
   `getBannerMode(environment)` was called twice; now computed once and reused. Avoids a redundant method call and reads more clearly.

2. **`prepareContext` → extract `configureBeanFactory` helper** (lines 386–423)  
   The nested pattern-matching instanceof block that sets circular-reference and bean-definition-overriding policies was inlined inside a 35-line method doing many other things. Extracted to `configureBeanFactory(ConfigurableListableBeanFactory)` so the responsibility is named and `prepareContext` reads as a higher-level sequence of steps.

3. **`addBootstrapRegistryInitializer` — use `add()` not `addAll(Arrays.asList(x))`** (line 1083)  
   The method takes a single `BootstrapRegistryInitializer`, not varargs. Wrapping it in `Arrays.asList()` just to call `addAll()` is unnecessary indirection — `list.add(item)` is the correct idiom for a single element.

**`JavaBeanBinder.java`** — 1 change:

4. **`determinePropertyName` — extract `annotations` variable** (lines 141–150)  
   `property.getAnnotations()` appeared twice in the same expression via the null-guard ternary `(x != null) ? x : new Annotation[0]`. The refactored version calls it once, stores the result, and returns early on `null` — eliminating the redundant call and flattening the stream chain.

Changes from the last iteration:

```diff
diff --git a/core/spring-boot/src/main/java/org/springframework/boot/SpringApplication.java b/core/spring-boot/src/main/java/org/springframework/boot/SpringApplication.java
index c5d5af28b..7c4ce0612 100644
--- a/core/spring-boot/src/main/java/org/springframework/boot/SpringApplication.java
+++ b/core/spring-boot/src/main/java/org/springframework/boot/SpringApplication.java
@@ -384,12 +384,7 @@ public class SpringApplication {
 		postProcessApplicationContext(context);
 		addAotGeneratedInitializerIfNecessary(this.initializers);
 		ConfigurableListableBeanFactory beanFactory = context.getBeanFactory();
-		if (beanFactory instanceof AbstractAutowireCapableBeanFactory autowireCapableBeanFactory) {
-			autowireCapableBeanFactory.setAllowCircularReferences(this.properties.isAllowCircularReferences());
-			if (beanFactory instanceof DefaultListableBeanFactory listableBeanFactory) {
-				listableBeanFactory.setAllowBeanDefinitionOverriding(this.properties.isAllowBeanDefinitionOverriding());
-			}
-		}
+		configureBeanFactory(beanFactory);
 		applyInitializers(context);
 		listeners.contextPrepared(context);
 		bootstrapContext.close(context);
@@ -418,6 +413,15 @@ public class SpringApplication {
 		listeners.contextLoaded(context);
 	}

+	private void configureBeanFactory(ConfigurableListableBeanFactory beanFactory) {
+		if (beanFactory instanceof AbstractAutowireCapableBeanFactory autowireCapableBeanFactory) {
+			autowireCapableBeanFactory.setAllowCircularReferences(this.properties.isAllowCircularReferences());
+			if (beanFactory instanceof DefaultListableBeanFactory listableBeanFactory) {
+				listableBeanFactory.setAllowBeanDefinitionOverriding(this.properties.isAllowBeanDefinitionOverriding());
+			}
+		}
+	}
+
 	private void addAotGeneratedInitializerIfNecessary(List<ApplicationContextInitializer<?>> initializers) {
 		if (AotDetector.useGeneratedArtifacts()) {
 			List<ApplicationContextInitializer<?>> aotInitializers = new ArrayList<>(
@@ -557,13 +561,14 @@ public class SpringApplication {
 	}

 	private @Nullable Banner printBanner(ConfigurableEnvironment environment) {
-		if (this.properties.getBannerMode(environment) == Banner.Mode.OFF) {
+		Banner.Mode bannerMode = this.properties.getBannerMode(environment);
+		if (bannerMode == Banner.Mode.OFF) {
 			return null;
 		}
 		ResourceLoader resourceLoader = (this.resourceLoader != null) ? this.resourceLoader
 				: new DefaultResourceLoader(null);
 		SpringApplicationBannerPrinter bannerPrinter = new SpringApplicationBannerPrinter(resourceLoader, this.banner);
-		if (this.properties.getBannerMode(environment) == Mode.LOG) {
+		if (bannerMode == Mode.LOG) {
 			return bannerPrinter.print(environment, this.mainApplicationClass, logger);
 		}
 		return bannerPrinter.print(environment, this.mainApplicationClass, System.out);
@@ -1075,7 +1080,7 @@ public class SpringApplication {
 	 */
 	public void addBootstrapRegistryInitializer(BootstrapRegistryInitializer bootstrapRegistryInitializer) {
 		Assert.notNull(bootstrapRegistryInitializer, "'bootstrapRegistryInitializer' must not be null");
-		this.bootstrapRegistryInitializers.addAll(Arrays.asList(bootstrapRegistryInitializer));
+		this.bootstrapRegistryInitializers.add(bootstrapRegistryInitializer);
 	}

 	/**
diff --git a/core/spring-boot/src/main/java/org/springframework/boot/context/properties/bind/JavaBeanBinder.java b/core/spring-boot/src/main/java/org/springframework/boot/context/properties/bind/JavaBeanBinder.java
index 335326635..9f999b8e6 100644
--- a/core/spring-boot/src/main/java/org/springframework/boot/context/properties/bind/JavaBeanBinder.java
+++ b/core/spring-boot/src/main/java/org/springframework/boot/context/properties/bind/JavaBeanBinder.java
@@ -139,7 +139,11 @@ class JavaBeanBinder implements DataObjectBinder {
 	}

 	private String determinePropertyName(BeanProperty property) {
-		return Arrays.stream((property.getAnnotations() != null) ? property.getAnnotations() : new Annotation[0])
+		Annotation[] annotations = property.getAnnotations();
+		if (annotations == null) {
+			return property.getName();
+		}
+		return Arrays.stream(annotations)
 			.filter((annotation) -> annotation.annotationType() == Name.class)
 			.findFirst()
 			.map(Name.class::cast)
